const files = $input.all().map(i => i.json);
const barcodeFolderId =
  files[0]?.parents?.[0] || '';
const barcode =
  (files[0]?.name || '')
    .replace(/-\d+\.[^.]+$/i, '');
const imageFiles = files.filter(f => (f.mimeType && f.mimeType.startsWith('image/')) || /\.(jpg|jpeg|png|webp)$/i.test(f.name || ''));
imageFiles.sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), undefined, { numeric: true }));
if (!imageFiles.length) return [{ json: { hasImages: false, reason: 'No image files found', barcode, barcodeFolderId } }];
const primary = imageFiles.find(f => /-4\.(jpg|jpeg|png|webp)$/i.test(f.name || '')) || imageFiles.find(f => /-1\.(jpg|jpeg|png|webp)$/i.test(f.name || '')) || imageFiles[0];
return [{ json: { hasImages: true, barcode, barcodeFolderId, primaryImageId: primary.id, primaryImageName: primary.name, imageIds: imageFiles.map(f => f.id), imageNames: imageFiles.map(f => f.name), imageLinks: imageFiles.map(f => 'https://drive.google.com/uc?id=' + f.id), imageCount: imageFiles.length, receivedAt: new Date().toISOString() } }];

const aiRaw = $input.first().json;
const product = $('Validate and Prepare Product1').first().json;

function findText(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (value.content && Array.isArray(value.content.parts)) return value.content.parts.map(part => part.text || '').join('\n');
  if (value.text) return String(value.text);
  if (value.output) return typeof value.output === 'string' ? value.output : findText(value.output);
  if (value.response) return typeof value.response === 'string' ? value.response : findText(value.response);
  if (Array.isArray(value)) { for (const entry of value) { const found = findText(entry); if (found) return found; } }
  if (typeof value === 'object') { for (const key of Object.keys(value)) { const found = findText(value[key]); if (found && found.includes('{')) return found; } }
  return JSON.stringify(value);
}

function cleanJsonText(text) {
  let cleaned = String(text || '').trim();
  if (cleaned.startsWith('```')) {
    const firstNewline = cleaned.indexOf('\n');
    if (firstNewline >= 0) cleaned = cleaned.slice(firstNewline + 1).trim();
    if (cleaned.endsWith('```')) cleaned = cleaned.slice(0, -3).trim();
  }
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace >= 0 && lastBrace > firstBrace) cleaned = cleaned.slice(firstBrace, lastBrace + 1);
  return cleaned;
}

function parseAi(value) {
  if (value && typeof value === 'object' && value.productTitle) return value;
  const text = findText(value);
  return JSON.parse(cleanJsonText(text));
}

function toArray(value) {
  if (Array.isArray(value)) return value.filter(Boolean).map(item => String(item).trim()).filter(Boolean);
  if (!value) return [];
  return String(value).split('\n').map(item => item.trim()).filter(Boolean);
}

function splitToLines(value) {
  if (!value) return [];
  const str = String(value);
  // Split on bullet-like chars, newlines, or sentence endings followed by capital
  return str.split(/(?:[\n•\-\*]|(?<=\.\s))/).map(s => s.replace(/^[\s\-•*]+/, '').trim()).filter(Boolean);
}

function onlyPrice(value) {
  const text = String(value || '');
  let out = '';
  for (const ch of text) if ('0123456789.'.includes(ch)) out += ch;
  return out;
}

let ai;
try { ai = parseAi(aiRaw); } catch (error) {
  ai = {
  productTitle: product.barcode,
  price: '',
  size: '',
  color: '',
  workDetails: '',
  sareeFabric: '',
  blouseFabric: '',
  sareeLength: '5.50 Meter',
  blouseLength: '0.80 Meter',
  sareeType: [],
  occasionWise: [],
  style: [],
  fabricCategory: [],
  washCare: ['Dry Clean Recommended'],
  tags: [],
  parseError: error.message,
  rawGemini: findText(aiRaw) };
}

const productTitle = ai.productTitle || product.barcode;
const price = onlyPrice(ai.price);
const size = ai.size || '';
const washCare = toArray(ai.washCare);
const collections = [
 ...(ai.sareeType || []),
 ...(ai.occasionWise || []),
 ...(ai.style || []),
 ...(ai.fabricCategory || [])
];
const tags = toArray(ai.tags);
for (const extra of collections) if (extra && !tags.includes(extra)) tags.push(extra);
if (ai.color && !tags.includes(ai.color)) tags.push(ai.color);
if (size && !tags.includes('Size ' + size)) tags.push('Size ' + size);

// Split multi-value fields into arrays for bullet rendering
const colorList = String(ai.color || '').split(/[,\n]/).map(c => c.trim()).filter(Boolean);
const workLines = splitToLines(ai.workDetails);

const fabricLines = [
 'Saree Fabric: ' + (ai.sareeFabric || ''),
 'Blouse Fabric: ' + (ai.blouseFabric || ''),
 'Saree Length: ' + (ai.sareeLength || '5.50 Meter'),
 'Blouse Length: ' + (ai.blouseLength || '0.80 Meter')
]
.join('<br>');
const descriptionHtml = '<h3>Work Details</h3><p>' + (ai.workDetails || '') + '</p><h3>Fabric Details</h3><p>' + fabricLines + '</p><h3>Wash Care</h3><ul>' + washCare.map(w => '<li>' + w + '</li>').join('') + '</ul>';

return [{
 json: {
  ...product,

  productTitle,
  price,
  size,

  color: ai.color || '',
  colorList,

  workLines,
  workDetails: ai.workDetails || '',

  sareeFabric: ai.sareeFabric || '',
  blouseFabric: ai.blouseFabric || '',

  sareeLength: ai.sareeLength || '5.50 Meter',
  blouseLength: ai.blouseLength || '0.80 Meter',

  washCare,
  collections,
  tags,

  descriptionHtml,
  aiParsed: ai
 }
}];

const folders = $input.all().map(i => i.json).filter(f =>
  f.mimeType === 'application/vnd.google-apps.folder'
);
const total = folders.length;
// Attach index (P1, P2 ... PN) and total to each folder item
return folders.map((folder, idx) => ({
  json: {
    ...folder,
    folderIndex: idx + 1,
    totalFolders: total,
    label: `P${idx + 1} of ${total}: ${folder.name}`
  }
}));

// Collect all completed items from Log to Google Sheets
const items = $input.all();
const total = items.length;
const labels = items.map((item, i) => {
  const b = item.json.barcode || item.json.name || `Folder ${i+1}`;
  return `P${i+1}: ${b}`;
});
return [{
  json: {
    summary: `✅ Processed ${total} folder(s)`,
    details: labels,
    completedAt: new Date().toISOString()
  }
}];

// ══════════════════════════════════════════════════════════════════════
// BUILD MARKDOWN · Shayona Product Sheet v2
// Fixed: sareeFabric/blouseFabric keys, sareeLength/blouseLength always
//        emitted, washCare fallback hardcoded, no duplicate fabric block
// ══════════════════════════════════════════════════════════════════════

const p = $('Parse and Merge AI Product Data1').first().json;
const ai = p.aiParsed || {};

const safeArr = (v) => Array.isArray(v) ? v.filter(x => String(x||'').trim()) : (v ? [String(v).trim()] : []);
const safe    = (v, fb='') => String(v||'').trim() || fb;
const bullets = (arr) => safeArr(arr).map(s => `- ${String(s).replace(/^[-•*]\s*/,'').trim()}`).join('\n');


const lines = [];

// Product Title
lines.push(`## Product Title`);
lines.push(safe(p.productTitle));
lines.push('');

// Price
lines.push(`## Price`);
lines.push(p.price ? `₹ ${p.price}` : '');
lines.push('');

// Color
lines.push(`## Color`);
const colorStr = safeArr(p.colorList).join(' & ') || safe(p.color);
lines.push(colorStr);
lines.push('');

// Work Details
lines.push(`## Work Details`);
const workArr = safeArr(p.workLines).length ? p.workLines : [p.workDetails];
lines.push(bullets(workArr));
lines.push('');

// Fabric Details

lines.push('## Fabric Details');
lines.push('');

lines.push(`- **Saree Fabric:** ${safe(ai.sareeFabric)}`);
lines.push('');

lines.push(`- **Blouse Fabric:** ${safe(ai.blouseFabric)}`);
lines.push('');

lines.push(`- **Saree Length:** ${safe(ai.sareeLength,'5.50 Meter')}`);
lines.push('');

lines.push(`- **Blouse Length:** ${safe(ai.blouseLength,'0.80 Meter')}`);
lines.push('');

// ── Wash Care ── with hardcoded fallback so it is NEVER empty
lines.push(`## Wash Care`);
const washItems = safeArr(p.washCare).length ? p.washCare : [
  'Dry Clean Only',
  'Store in a cool, dry place',
  'Keep wrapped in a muslin cloth for fabric longevity',
  'Avoid direct exposure to sunlight for prolonged periods',
  'Iron on low heat from the reverse side'
];
washItems.forEach(item => {
  lines.push(`- ${item}`);
});

lines.push('');

// Collections
lines.push(`## Collections`);
lines.push(bullets(p.collections));

const markdown = lines.join('\n');
return [{ json: { ...p, markdown } }];

// ══════════════════════════════════════════════════════════════════════
// INJECT CSS STYLES · Shayona Product Sheet
// Matches exact DOCX format spec:
//   Headings: Cambria, 17pt, bold, #3D85C6
//   Body:     IBM Plex Sans, 11pt, black
//   Bullets:  ● filled circle, indent 0.5", hanging 0.25"
//   Fabric:   label (auto color) + value (auto color) inline
//   Wash Care: inline • bullets
//   Page:     US Letter, 1" margins
// ══════════════════════════════════════════════════════════════════════

const p   = $('Parse and Merge AI Product Data1').first().json;
let raw = $input.first().json.html || $input.first().json.data || '';

// Post-process: convert FABRIC_LABEL / WASH_ITEM / FABRIC_VALUE markers
// (they arrive as <p> tags from markdown conversion)
raw = raw.replace(
  /<p>FABRIC_LABEL:([^|]+)\|FABRIC_VALUE:(.*?)<\/p>/g,
  (_, label, value) =>
    `<p class="fabric-row"><span class="fabric-label">${label} </span><span class="fabric-value">${value}</span></p>`
);
raw = raw.replace(
  /<p>WASH_ITEM:(.*?)<\/p>/g,
  (_, item) => `<p class="wash-item"> • ${item}</p>`
);

// Fix list items: replace "- " bullets from markdown with proper ● bullets
// Markdown converts "- item" to <li>item</li> — we keep those and style them

const styledHtml = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  /* ── Page ── */
  @page { size: 8.5in 11in; margin: 1in; }
  body {
    font-family: 'IBM Plex Sans', Arial, sans-serif;
    font-size: 11pt;
    color: #000000;
    margin: 72px 72px;
    line-height: 1.15;
    background: #fff;
  }

  /* ── Section headings (Heading 2 → Cambria 17pt bold #3D85C6) ── */
  h2 {
    font-family: 'Cambria', 'Georgia', serif;
    font-size: 17pt;
    font-weight: bold;
    color: #3d85c6;
    margin-top: 14px;
    margin-bottom: 2px;
    line-height: 1.2;
  }

  /* ── Body paragraphs (IBM Plex Sans 11pt, spacing ~0.15") ── */
  p {
    font-family: 'IBM Plex Sans', Arial, sans-serif;
    font-size: 11pt;
    color: #000000;
    margin-top: 11px;
    margin-bottom: 11px;
    line-height: 1.15;
  }

  /* ── Bullet lists: ● filled circle, 0.5" indent, 0.25" hanging ── */
  ul {
    margin: 2px 0 11px 0;
    padding-left: 0;
    list-style: none;
  }
  ul li {
    font-family: 'IBM Plex Sans', Arial, sans-serif;
    font-size: 11pt;
    color: #000000;
    padding-left: 36px;
    text-indent: -18px;
    margin: 0;
    line-height: 1.3;
  }
  ul li::before {
    content: "● ";
    font-size: 10pt;
  }

  /* ── Fabric Details: label in normal weight, value in normal weight ── */
  p.fabric-row {
    margin-top: 11px;
    margin-bottom: 11px;
  }
  span.fabric-label {
    font-family: 'IBM Plex Sans', Arial, sans-serif;
    font-size: 11pt;
    color: #000000;
    font-weight: normal;
  }
  span.fabric-value {
    font-family: 'IBM Plex Sans', Arial, sans-serif;
    font-size: 11pt;
    color: #333333;
    font-weight: normal;
  }

  /* ── Wash Care: inline • bullets (IBM Plex Sans 11pt) ── */
  p.wash-item {
    font-family: 'IBM Plex Sans', Arial, sans-serif;
    font-size: 11pt;
    color: #000000;
    margin: 2px 0;
  }

  /* ── Inline section heads (Wash Care, Collections) ──
     These are h2 tags so already styled correctly above ── */
</style>
</head>
<body>
${raw}
</body>
</html>`;

const docTitle = (p.barcode || 'product') ;
const base64 = Buffer.from(styledHtml, 'utf8').toString('base64');

return [{
  json: { ...p, styledHtml, docTitle },
  binary: {
    data: {
      data:          base64,
      mimeType:      'text/html',
      fileName:      docTitle + '.html',
      fileExtension: 'html'
    }
  }
}];

const p = $json;

const productJson = {
 title: p.productTitle,
 price: p.price,
 size: p.size,
 color: p.color,

 sareeFabric: p.aiParsed?.sareeFabric,
 blouseFabric: p.aiParsed?.blouseFabric,

 sareeType: p.aiParsed?.sareeType,
 occasionWise: p.aiParsed?.occasionWise,
 style: p.aiParsed?.style,
 fabricCategory: p.aiParsed?.fabricCategory,

 tags: p.tags,
 collections: p.collections,

 descriptionHtml: p.descriptionHtml,
 barcode: p.barcode
};

const jsonString = JSON.stringify(productJson, null, 2);

return [{
  json: p,
  binary: {
    data: {
      data: Buffer.from(jsonString).toString('base64'),
      mimeType: 'application/json',
      fileName: 'product.json'
    }
  }
}];
